    public int binaryToDecimal(int binaryNumber) {
        if (binaryNumber < 0)
            return -1;

        int decimalNumber = 0;
        int tempNumber = binaryNumber;
        int multiplikator = 0;

        for (int i = 0; tempNumber > 0; i++) {
            multiplikator = tempNumber % 10;
            decimalNumber = decimalNumber + multiplikator * (int) Math.pow(2, i);
            tempNumber = tempNumber / 10;
        }

        return decimalNumber;
    }



	public int countSameCharsAtSamePosition(String word1, String word2) {
		int shortestLength;

		if (word1.length() < word2.length())
			shortestLength = word1.length();
		else
			shortestLength = word2.length();

		int sameCharsAtSamePosition = 0;

		for (int i = 0; i < shortestLength; i++) {
			if (word1.charAt(i) == word2.charAt(i)) {
				sameCharsAtSamePosition++;
			}
		}

		return sameCharsAtSamePosition;
	}



    public String intertwineTwoWords(String word1, String word2) {
        String intertwinedWord = "";

        if (word1.length() == word2.length()) {
            for (int i = 0; i < word1.length(); i++) {
                intertwinedWord = intertwinedWord + word1.charAt(i)
                        + word2.charAt(i);
            }
        }

        return intertwinedWord;
    }




    public Integer firstAboveTreshold(int[] numberArray, int threshold) {
        for (int i = 0; i < numberArray.length; i++) {
            int numberToTest = numberArray[i];

            if (numberToTest > threshold) {
                return numberToTest;
            }
        }

        return null;
    }



    public double[] squareRoots(int[] array) {
        double[] squareRootArray = new double[array.length];

        for (int i = 0; i < array.length; i++) {
            if (array[i] < 0) {
                squareRootArray[i] = Math.sqrt(-1 * array[i]);
            } else {
                squareRootArray[i] = Math.sqrt(array[i]);
            }
        }

        return squareRootArray;
    }



    public boolean isPalindrome(String word) {
        boolean isPalindrome = true;

        for (int i = 0, j = word.length() - 1; i < word.length() / 2; i++, j--) {
            if (word.charAt(i) != word.charAt(j)) {
                isPalindrome = false;
                break;
            }
        }

        return isPalindrome;
    }



